  1	declare const storageObjectIdBrand: unique symbol;
  2	declare const generationIdBrand: unique symbol;
  3	declare const blobDigestBrand: unique symbol;
  4	declare const closureDigestBrand: unique symbol;
  5	declare const headRevisionBrand: unique symbol;
  6	declare const generationPageCursorBrand: unique symbol;
  7	
  8	export type StorageObjectId = string & { readonly [storageObjectIdBrand]: true };
  9	export type GenerationId = string & { readonly [generationIdBrand]: true };
 10	export type BlobDigest = string & { readonly [blobDigestBrand]: true };
 11	export type ClosureDigest = string & { readonly [closureDigestBrand]: true };
 12	export type HeadRevision = number & { readonly [headRevisionBrand]: true };
 13	export type GenerationPageCursor = string & { readonly [generationPageCursorBrand]: true };
 14	
 15	export type ParseResult<T> =
 16		| { readonly ok: true; readonly value: T }
 17		| { readonly ok: false; readonly reason: "INVALID_ARGUMENT" | "SHARED_BUFFER_INPUT" };
 18	
 19	export type StorageRejectionReason =
 20		| "STORE_CLOSED"
 21		| "STORE_POISONED"
 22		| "INVALID_ARGUMENT"
 23		| "SHARED_BUFFER_INPUT"
 24		| "GENERATION_NOT_FOUND"
 25		| "GENERATION_EXISTS"
 26		| "ILLEGAL_TRANSITION"
 27		| "EMPTY_CLOSURE"
 28		| "DUPLICATE_CLOSURE_REFERENCE"
 29		| "BLOB_NOT_REFERENCED"
 30		| "BLOB_MISSING"
 31		| "BLOB_CORRUPT"
 32		| "BLOB_UNPROMOTED"
 33		| "ADOPTED_BLOB_UNPROMOTED"
 34		| "ADOPTED_BLOB_MISSING"
 35		| "ADOPTED_BLOB_CORRUPT"
 36		| "IMMUTABLE_CONFLICT"
 37		| "DURABILITY_UNAVAILABLE"
 38		| "BASE_HEAD_MISMATCH"
 39		| "CANDIDATE_NOT_COMPLETE"
 40		| "HEAD_CONFLICT"
 41		| "REVISION_EXHAUSTED"
 42		| "UNSUPPORTED_STORAGE_SCHEMA"
 43		| "NON_CANONICAL_RECORD"
 44		| "SUBSTRATE_FAILURE";
 45	
 46	export type StoreResult<T> =
 47		| { readonly ok: true; readonly value: T }
 48		| {
 49				readonly ok: false;
 50				readonly reason: Exclude<StorageRejectionReason, "SUBSTRATE_FAILURE">;
 51		  }
 52		| { readonly ok: false; readonly reason: "SUBSTRATE_FAILURE"; readonly cause: unknown };
 53	
 54	export type NoHead = {
 55		readonly kind: "none";
 56		readonly objectId: StorageObjectId;
 57	};
 58	
 59	export type PresentHead = {
 60		readonly kind: "present";
 61		readonly objectId: StorageObjectId;
 62		readonly generationId: GenerationId;
 63		readonly revision: HeadRevision;
 64		readonly closureDigest: ClosureDigest;
 65	};
 66	
 67	export type ExpectedHead = NoHead | PresentHead;
 68	
 69	export type GenerationRef = {
 70		readonly digest: BlobDigest;
 71		readonly byteLength: number;
 72	};
 73	
 74	export type GenerationState = "Staged" | "Complete" | "Adopted" | "Superseded" | "Discarded";
 75	
 76	export type GenerationRecord = {
 77		readonly objectId: StorageObjectId;
 78		readonly generationId: GenerationId;
 79		readonly baseExpectedHead: ExpectedHead;
 80		readonly closureDigest: ClosureDigest;
 81		readonly closure: readonly GenerationRef[];
 82		readonly state: GenerationState;
 83	};
 84	
 85	export type GenerationPage = {
 86		readonly generations: readonly GenerationRecord[];
 87		readonly nextCursor: GenerationPageCursor | null;
 88	};
 89	export type ActiveGenerationSnapshot =
 90		| Readonly<{
 91				kind: "empty";
 92				head: NoHead;
 93				adoptedGeneration: null;
 94				recomputedClosureDigest: null;
 95				references: readonly [];
 96		  }>
 97		| Readonly<{
 98				kind: "active";
 99				head: PresentHead;
100				adoptedGeneration: GenerationRecord;
101				recomputedClosureDigest: ClosureDigest;
102				references: readonly GenerationRef[];
103		  }>;
104	
105	export type StoreCapabilities = {
106		readonly durability: "ephemeral" | "strict";
107		readonly signingEligibility: "never" | "backend-capability-required";
108	};
109	
110	export interface AheDurableStore {
111		readonly capabilities: Readonly<StoreCapabilities>;
112		readHead(objectId: StorageObjectId): Promise<StoreResult<ExpectedHead>>;
113		readGenerationPage(input: {
114			readonly objectId: StorageObjectId;
115			readonly cursor?: GenerationPageCursor;
116			readonly limit: number;
117		}): Promise<StoreResult<GenerationPage>>;
118		recoverActiveGeneration(objectId: StorageObjectId): Promise<StoreResult<ActiveGenerationSnapshot>>;
119		getBlob(digest: BlobDigest): Promise<StoreResult<Uint8Array | null>>;
120		beginGeneration(input: {
121			readonly objectId: StorageObjectId;
122			readonly generationId: GenerationId;
123			readonly baseExpectedHead: ExpectedHead;
124			readonly closure: readonly GenerationRef[];
125		}): Promise<StoreResult<GenerationRecord>>;
126		putCachedBlob(input: {
127			readonly objectId: StorageObjectId;
128			readonly generationId: GenerationId;
129			readonly digest: BlobDigest;
130			readonly bytes: Uint8Array;
131		}): Promise<StoreResult<{ readonly inserted: boolean }>>;
132		promoteReference(input: {
133			readonly objectId: StorageObjectId;
134			readonly generationId: GenerationId;
135			readonly digest: BlobDigest;
136		}): Promise<StoreResult<undefined>>;
137		completeGeneration(input: {
138			readonly objectId: StorageObjectId;
139			readonly generationId: GenerationId;
140		}): Promise<StoreResult<GenerationRecord>>;
141		swapHead(input: {
142			readonly objectId: StorageObjectId;
143			readonly generationId: GenerationId;
144			readonly expectedHead: ExpectedHead;
145		}): Promise<StoreResult<{ readonly head: PresentHead; readonly supersededGenerationId: GenerationId | null }>>;
146		discardGeneration(input: {
147			readonly objectId: StorageObjectId;
148			readonly generationId: GenerationId;
149		}): Promise<StoreResult<GenerationRecord>>;
150		close(): Promise<void>;
151	}

