171				(afterGenerationId !== null && !isGenerationId(afterGenerationId)) ||
172				!Number.isSafeInteger(limit) ||
173				limit < 1 ||
174				limit > MAX_INTERNAL_GENERATION_PAGE_ROWS
175			) {
176				return rejected("INVALID_ARGUMENT");
177			}
178			const lifecycleFailure = this.lifecycleFailure();
179			if (lifecycleFailure !== undefined) return lifecycleFailure;
180			const object = this.objects.get(objectId);
181			if (object === undefined) return { ok: true, value: [] };
182			const start = firstGenerationAfter(object.generationIds, afterGenerationId);
183			const end = Math.min(start + limit, object.generationIds.length);
184			const generations: GenerationRecord[] = [];
185			for (let index = start; index < end; index++) {
186				const generationId = object.generationIds[index];
187				if (generationId === undefined) throw new Error("ordered generation index is sparse");
188				generations.push(indexedGenerationRecord(object, generationId));
189			}
190			return { ok: true, value: generations };
191		}
