202		): StoreResult<GenerationRecord | null> {
203			if (!isStorageObjectId(objectId) || !isGenerationId(generationId)) return rejected("INVALID_ARGUMENT");
204			const lifecycleFailure = this.lifecycleFailure();
205			if (lifecycleFailure !== undefined) return lifecycleFailure;
206			const generation = this.findGeneration(objectId, generationId);
207			return { ok: true, value: generation === undefined ? null : asRecord(generation) };
208		}
209	
210		/**
211		 * Reads fresh bytes for one global content-addressed blob.
212		 * @param digest - Input value.
213		 * @returns Fresh blob bytes, absence, or stable rejection.
214		 */
215		public getBlob(digest: BlobDigest): StoreResult<Uint8Array | null> {
216			if (!isBlobDigest(digest)) return rejected("INVALID_ARGUMENT");
217			const lifecycleFailure = this.lifecycleFailure();
218			if (lifecycleFailure !== undefined) return lifecycleFailure;
219			const value = this.blobs.get(digest);
220			return { ok: true, value: value === undefined ? null : new Uint8Array(value) };
221		}
222	
223		/**
224		 * Captures a new immutable Staged generation.
225		 * @param input - Input value.
226		 * @param input.objectId - Input value.
227		 * @param input.generationId - Input value.
228		 * @param input.baseExpectedHead - Input value.
229		 * @param input.closure - Input value.
230		 * @returns The staged record or stable rejection.
231		 */
232		public beginGeneration(input: {
233			objectId: StorageObjectId;
234			generationId: GenerationId;
235			baseExpectedHead: ExpectedHead;
236			closure: readonly GenerationRef[];
237		}): StoreResult<GenerationRecord> {
238			if (!isClosedRecord(input, ["objectId", "generationId", "baseExpectedHead", "closure"])) {
239				return rejected("INVALID_ARGUMENT");
240			}
241			if (!isStorageObjectId(input.objectId) || !isGenerationId(input.generationId)) {
242				return rejected("INVALID_ARGUMENT");
243			}
244			const baseExpectedHead = copyExpectedHead(input.baseExpectedHead, input.objectId);
245			if (baseExpectedHead === undefined || !isClosedArray(input.closure)) return rejected("INVALID_ARGUMENT");
246			const closure: GenerationRef[] = [];
247			for (const value of input.closure) {
248				const copied = copyGenerationRef(value);
249				if (copied === undefined) return rejected("INVALID_ARGUMENT");
250				closure.push(copied);
251			}
252			const lifecycleFailure = this.lifecycleFailure();
253			if (lifecycleFailure !== undefined) return lifecycleFailure;
254			const existingObject = this.objects.get(input.objectId);
255			if (existingObject?.generations.has(input.generationId) === true) return rejected("GENERATION_EXISTS");
256			const currentHead = existingObject?.head ?? { kind: "none" as const, objectId: input.objectId };
257			if (!headsEqual(currentHead, baseExpectedHead)) return rejected("BASE_HEAD_MISMATCH");
258			if (closure.length === 0) return rejected("EMPTY_CLOSURE");
259			closure.sort((left, right) => compareCanonicalText(left.digest, right.digest));
260			for (let index = 1; index < closure.length; index++) {
261				if (closure[index - 1]?.digest === closure[index]?.digest) {
262					return rejected("DUPLICATE_CLOSURE_REFERENCE");
263				}
264			}
265			const object = existingObject ?? this.object(input.objectId);
266			const closureDigest = digestClosure(closure);
267			if (!closureDigest.ok) return rejected("INVALID_ARGUMENT");
268			const generation: MutableGeneration = {
269				objectId: input.objectId,
270				generationId: input.generationId,
271				baseExpectedHead,
272				closureDigest: closureDigest.value,
273				closure,
274				state: "Staged",
275			};
276			object.generations.set(input.generationId, generation);
277			insertGenerationId(object.generationIds, input.generationId);
278			return { ok: true, value: asRecord(generation) };
279		}
280	
281		/**
282		 * Inserts or idempotently observes one declared global cached blob.
283		 * @param input - Input value.
284		 * @param input.objectId - Input value.
285		 * @param input.generationId - Input value.
286		 * @param input.digest - Input value.
287		 * @param input.bytes - Input value.
288		 * @returns Whether insertion won or a stable rejection.
289		 */
290		public putCachedBlob(input: {
291			objectId: StorageObjectId;
292			generationId: GenerationId;
293			digest: BlobDigest;
294			bytes: Uint8Array;
295		}): StoreResult<{ inserted: boolean }> {
296			if (typeof input !== "object" || input === null) return rejected("INVALID_ARGUMENT");
297			const bytesDescriptor = Object.getOwnPropertyDescriptor(input, "bytes");
298			if (
299				bytesDescriptor === undefined ||
300				!("value" in bytesDescriptor) ||
301				!(bytesDescriptor.value instanceof Uint8Array)
302			) {
303				return rejected("INVALID_ARGUMENT");
304			}
305			if (hasSharedBacking(bytesDescriptor.value)) return rejected("SHARED_BUFFER_INPUT");
306			const bytes = new Uint8Array(bytesDescriptor.value);
307			if (!isClosedRecord(input, ["objectId", "generationId", "digest", "bytes"])) {
308				return rejected("INVALID_ARGUMENT");
309			}
310			if (!isStorageObjectId(input.objectId) || !isGenerationId(input.generationId) || !isBlobDigest(input.digest)) {
311				return rejected("INVALID_ARGUMENT");
312			}
313			const lifecycleFailure = this.lifecycleFailure();
314			if (lifecycleFailure !== undefined) return lifecycleFailure;
315			const generation = this.findGeneration(input.objectId, input.generationId);
316			if (generation === undefined) return rejected("GENERATION_NOT_FOUND");
317			if (generation.state !== "Staged") return rejected("ILLEGAL_TRANSITION");
318			if (!generation.closure.some(({ digest }) => digest === input.digest)) return rejected("BLOB_NOT_REFERENCED");
319			const existing = this.blobs.get(input.digest);
320			if (existing !== undefined) {
321				return bytesEqual(existing, bytes) ? { ok: true, value: { inserted: false } } : rejected("IMMUTABLE_CONFLICT");
322			}
323			this.blobs.set(input.digest, bytes);
324			return { ok: true, value: { inserted: true } };
325		}
326	
327		/**
328		 * Verifies one strict reference and records backend-owned promotion evidence.
329		 * @param input - Input value.
330		 * @param input.objectId - Input value.
331		 * @param input.generationId - Input value.
332		 * @param input.digest - Input value.
333		 * @returns Success or a stable rejection.
334		 */
335		public promoteReference(input: {
336			objectId: StorageObjectId;
337			generationId: GenerationId;
338			digest: BlobDigest;
339		}): StoreResult<undefined> {
340			if (!this.validGenerationDigestInput(input)) return rejected("INVALID_ARGUMENT");
341			const lifecycleFailure = this.lifecycleFailure();
342			if (lifecycleFailure !== undefined) return lifecycleFailure;
343			if (this.durability === "ephemeral") return rejected("DURABILITY_UNAVAILABLE");
344			const generation = this.findGeneration(input.objectId, input.generationId);
345			if (generation === undefined) return rejected("GENERATION_NOT_FOUND");
346			if (generation.state !== "Staged") return rejected("ILLEGAL_TRANSITION");
347			const reference = generation.closure.find(({ digest }) => digest === input.digest);
348			if (reference === undefined) return rejected("BLOB_NOT_REFERENCED");
349			const blob = this.blobs.get(input.digest);
350			if (blob === undefined) return rejected("BLOB_MISSING");
351			if (!this.blobMatches(reference, blob)) return rejected("BLOB_CORRUPT");
352			this.promoted.add(this.promotionKey(input.objectId, input.generationId, input.digest));
353			return { ok: true, value: undefined };
354		}
355	
356		/**
357		 * Completes a staged generation only after every reference is promoted.
358		 * @param input - Input value.
359		 * @param input.objectId - Input value.
360		 * @param input.generationId - Input value.
361		 * @returns The completed record or stable rejection.
362		 */
363		public completeGeneration(input: {
364			objectId: StorageObjectId;
365			generationId: GenerationId;
366		}): StoreResult<GenerationRecord> {
367			if (!this.validGenerationInput(input)) return rejected("INVALID_ARGUMENT");
368			const lifecycleFailure = this.lifecycleFailure();
369			if (lifecycleFailure !== undefined) return lifecycleFailure;
370			const generation = this.findGeneration(input.objectId, input.generationId);
371			if (generation === undefined) return rejected("GENERATION_NOT_FOUND");
372			if (generation.state !== "Staged") return rejected("ILLEGAL_TRANSITION");
373			const authorization = this.verifyGenerationClosure(generation, "candidate");
374			if (!authorization.ok) return authorization;
375			generation.state = "Complete";
376			return { ok: true, value: asRecord(generation) };
377		}
378	
379		/**
380		 * Completes a staged generation using verifier-issued authority.
381		 * @param input - Addressed staged generation.
382		 * @param input.objectId - Canonical object identity.
383		 * @param input.generationId - Canonical generation identity.
384		 * @param authorization - Exact candidate-closure authorization.
385		 * @returns The completed generation or stable rejection.
386		 */
387		public completeGenerationAuthorized(
388			input: { objectId: StorageObjectId; generationId: GenerationId },
389			authorization: Authorization
390		): StoreResult<GenerationRecord> {
391			if (!this.validGenerationInput(input)) return rejected("INVALID_ARGUMENT");
392			const lifecycleFailure = this.lifecycleFailure();
393			if (lifecycleFailure !== undefined) return lifecycleFailure;
394			const generation = this.findGeneration(input.objectId, input.generationId);
395			if (generation === undefined) return rejected("GENERATION_NOT_FOUND");
396			if (generation.state !== "Staged") return rejected("ILLEGAL_TRANSITION");
397			if (!accepts(authorization, asRecord(generation), "candidate")) return rejected("INVALID_ARGUMENT");
398			generation.state = "Complete";
399			return { ok: true, value: asRecord(generation) };
400		}
401	
402		/**
403		 * Recovers and verifies the one active generation at a stable snapshot.
404		 * @param objectId - Canonical object identity.
405		 * @returns Frozen recovery metadata or the first integrity failure.
406		 */
407		public recoverActiveGeneration(objectId: StorageObjectId): StoreResult<ActiveGenerationSnapshot> {
408			if (!isStorageObjectId(objectId)) return rejected("INVALID_ARGUMENT");
409			const lifecycleFailure = this.lifecycleFailure();
410			if (lifecycleFailure !== undefined) return lifecycleFailure;
411	
412			const object = this.objects.get(objectId);
413			const head = object === undefined ? ({ kind: "none", objectId } as const) : cloneHead(object.head);
414			let adoptedCount = 0;
415			let adoptedGeneration: MutableGeneration | undefined;
416			if (object !== undefined) {
417				for (const generationId of object.generationIds) {
418					const generation = indexedGeneration(object, generationId);
419					if (generation.state !== "Adopted") continue;
420					adoptedCount += 1;
421					adoptedGeneration = adoptedCount === 1 ? generation : undefined;
422				}
423			}
424			const relationalFailure =
425				(head.kind === "none" && adoptedCount !== 0) ||
426				(head.kind === "present" &&
427					(adoptedCount !== 1 ||
428						adoptedGeneration?.generationId !== head.generationId ||
429						adoptedGeneration.closureDigest !== head.closureDigest));
430			if (relationalFailure) return this.latchIntegrityFailure("NON_CANONICAL_RECORD");
431	
432			if (head.kind === "none") {
433				return {
434					ok: true,
435					value: freezeRecoverySnapshot({
436						kind: "empty",
437						head,
438						adoptedGeneration: null,
439						recomputedClosureDigest: null,
440						references: [],
441					}),
442				};
443			}
444	
445			const generation = adoptedGeneration;
446			if (generation === undefined) return this.latchIntegrityFailure("NON_CANONICAL_RECORD");
447			const verification = this.verifyGenerationClosure(generation, "adopted");
448			if (!verification.ok) {
449				if (verification.reason === "SUBSTRATE_FAILURE") throw new Error("in-memory verifier returned substrate failure");
450				return this.latchIntegrityFailure(verification.reason);
451			}
452			return {
453				ok: true,
454				value: freezeRecoverySnapshot({
455					kind: "active",
456					head: { ...head },
457					adoptedGeneration: cloneGeneration(generation),
458					recomputedClosureDigest: generation.closureDigest,
459					references: generation.closure.map((reference) => ({ ...reference })),
460				}),
461			};
462		}
463	
464		/**
465		 * Atomically adopts one Complete generation under exact expected-head CAS.
466		 * @param input - Input value.
467		 * @param input.objectId - Input value.
468		 * @param input.generationId - Input value.
469		 * @param input.expectedHead - Input value.
470		 * @returns The adopted head and superseded ID or stable rejection.
471		 */
472		public swapHead(input: {
473			objectId: StorageObjectId;
474			generationId: GenerationId;
475			expectedHead: ExpectedHead;
476		}): StoreResult<{ head: PresentHead; supersededGenerationId: GenerationId | null }> {
477			const candidate = this.preflightSwap(input);
478			if (!candidate.ok) return candidate;
479			const authorization = this.verifyGenerationClosure(candidate.value.generation, "candidate");
480			if (!authorization.ok) return authorization;
481			return this.adoptVerifiedSwap(candidate.value, authorization.value);
482		}
483	
484		/**
485		 * Adopts a candidate using verifier-issued authority after semantic preflight.
486		 * @param input - Exact compare-and-swap request.
487		 * @param input.objectId - Canonical object identity.
488		 * @param input.generationId - Complete candidate identity.
489		 * @param input.expectedHead - Exact expected head.
490		 * @param authorization - Exact candidate-closure authorization.
491		 * @returns The adopted head and superseded generation, or stable rejection.
492		 */
493		public swapHeadAuthorized(
494			input: {
495				objectId: StorageObjectId;
496				generationId: GenerationId;
497				expectedHead: ExpectedHead;
498			},
499			authorization: Authorization
500		): StoreResult<{ head: PresentHead; supersededGenerationId: GenerationId | null }> {
501			const candidate = this.preflightSwap(input);
502			if (!candidate.ok) return candidate;
503			return this.adoptVerifiedSwap(candidate.value, authorization);
504		}
505	
506		private preflightSwap(input: {
507			objectId: StorageObjectId;
508			generationId: GenerationId;
509			expectedHead: ExpectedHead;
510		}): StoreResult<SwapCandidate> {
511			if (!isClosedRecord(input, ["objectId", "generationId", "expectedHead"])) {
512				return rejected("INVALID_ARGUMENT");
513			}
514			if (!isStorageObjectId(input.objectId) || !isGenerationId(input.generationId)) {
515				return rejected("INVALID_ARGUMENT");
516			}
517			const expectedHead = copyExpectedHead(input.expectedHead, input.objectId);
518			if (expectedHead === undefined) return rejected("INVALID_ARGUMENT");
519			const lifecycleFailure = this.lifecycleFailure();
520			if (lifecycleFailure !== undefined) return lifecycleFailure;
521			const object = this.objects.get(input.objectId);
522			const generation = object?.generations.get(input.generationId);
523			if (object === undefined || generation === undefined) return rejected("GENERATION_NOT_FOUND");
524			if (generation.state !== "Complete") return rejected("CANDIDATE_NOT_COMPLETE");
525			if (!headsEqual(object.head, expectedHead)) return rejected("HEAD_CONFLICT");
526			if (!headsEqual(generation.baseExpectedHead, expectedHead)) return rejected("BASE_HEAD_MISMATCH");
527			if (expectedHead.kind === "present" && expectedHead.revision === Number.MAX_SAFE_INTEGER) {
528				return rejected("REVISION_EXHAUSTED");
529			}
530			return { ok: true, value: { object, generation, expectedHead } };
531		}
532	
533		private adoptVerifiedSwap(
534			candidate: SwapCandidate,
535			authorization: Authorization
536		): StoreResult<{ head: PresentHead; supersededGenerationId: GenerationId | null }> {
537			const { expectedHead, generation, object } = candidate;
538			if (!accepts(authorization, asRecord(generation), "candidate")) return rejected("INVALID_ARGUMENT");
539			const revision = checkedHeadRevision(expectedHead.kind === "none" ? 1 : expectedHead.revision + 1);
540			let supersededGenerationId: GenerationId | null = null;
541			if (object.head.kind === "present") {
542				const previous = object.generations.get(object.head.generationId);
543				if (previous !== undefined && previous.state === "Adopted") {
544					previous.state = "Superseded";
545					supersededGenerationId = previous.generationId;
546				}
547			}
548			generation.state = "Adopted";
549			const head: PresentHead = {
550				kind: "present",
551				objectId: generation.objectId,
552				generationId: generation.generationId,
553				revision,
554				closureDigest: generation.closureDigest,
555			};
556			object.head = head;
557			return { ok: true, value: { head: { ...head }, supersededGenerationId } };
558		}
559	
560		private verifyGenerationClosure(
561			generation: GenerationRecord,
562			mode: "adopted" | "candidate"
563		): StoreResult<Authorization> {
564			const session = start(generation, mode);
565			for (let request = next(session); request !== null; request = next(session)) {
566				if (request.kind === "promotion") {
567					acceptPromotion(
568						session,
569						this.promoted.has(this.promotionKey(generation.objectId, generation.generationId, request.reference.digest))
570					);
571				} else {
572					acceptBlob(session, this.blobs.get(request.reference.digest));
573				}
574			}
575			return finish(session);
576		}
577	
578		/**
579		 * Discards one Staged or Complete generation.
580		 * @param input - Input value.
581		 * @param input.objectId - Input value.
582		 * @param input.generationId - Input value.
583		 * @returns The discarded record or stable rejection.
584		 */
585		public discardGeneration(input: {
586			objectId: StorageObjectId;
587			generationId: GenerationId;
588		}): StoreResult<GenerationRecord> {
589			if (!this.validGenerationInput(input)) return rejected("INVALID_ARGUMENT");
590			const lifecycleFailure = this.lifecycleFailure();
591			if (lifecycleFailure !== undefined) return lifecycleFailure;
592			const generation = this.findGeneration(input.objectId, input.generationId);
593			if (generation === undefined) return rejected("GENERATION_NOT_FOUND");
594			if (generation.state !== "Staged" && generation.state !== "Complete") {
595				return rejected("ILLEGAL_TRANSITION");
596			}
597			generation.state = "Discarded";
598			return { ok: true, value: asRecord(generation) };
599		}
600	
601		/** Idempotently closes this transition owner. */
602		public close(): void {
603			this.closed = true;
604		}
605	
606		/**
607		 * Seeds modeled adapter state for package-internal conformance tests.
608		 * @param state - Input value.
609		 */
610		public seedObjectState(state: TransitionObjectState): void {
611			const generations = new Map(
612				state.generations.map((record) => {
613					const copied = cloneGeneration(record);
614					return [copied.generationId, { ...copied, closure: copied.closure.map((item) => ({ ...item })) }];
615				})
616			);
617			this.objects.set(state.head.objectId, {
618				head: cloneHead(state.head),
619				generations,
620				generationIds: [...generations.keys()].sort(compareCanonicalText),
621			});
622		}
623	
624		/**
625		 * Seeds a detached modeled backend blob for package-internal tests.
626		 * @param digest - Input value.
627		 * @param bytes - Input value.
628		 */
629		public seedBlob(digest: BlobDigest, bytes: Uint8Array): void {
630			this.blobs.set(digest, new Uint8Array(bytes));
631		}
632	
633		/**
634		 * Marks modeled backend-owned promotion evidence for package-internal tests.
635		 * @param objectId - Input value.
636		 * @param generationId - Input value.
637		 * @param digest - Input value.
638		 */
639		public markPromoted(objectId: StorageObjectId, generationId: GenerationId, digest: BlobDigest): void {
640			this.promoted.add(this.promotionKey(objectId, generationId, digest));
641		}
642	
643		private object(objectId: StorageObjectId): MutableObject {
644			let value = this.objects.get(objectId);
645			if (value === undefined) {
646				value = { head: { kind: "none", objectId }, generations: new Map(), generationIds: [] };
647				this.objects.set(objectId, value);
648			}
649			return value;
650		}
651	
652		private findGeneration(objectId: StorageObjectId, generationId: GenerationId): MutableGeneration | undefined {
653			return this.objects.get(objectId)?.generations.get(generationId);
654		}
655	
656		private validGenerationInput(value: unknown): value is { objectId: StorageObjectId; generationId: GenerationId } {
657			return (
658				isClosedRecord(value, ["objectId", "generationId"]) &&
659				isStorageObjectId(value.objectId) &&
660				isGenerationId(value.generationId)
661			);
662		}
663	
664		private validGenerationDigestInput(value: unknown): value is {
665			objectId: StorageObjectId;
666			generationId: GenerationId;
667			digest: BlobDigest;
668		} {
669			return (
670				isClosedRecord(value, ["objectId", "generationId", "digest"]) &&
671				isStorageObjectId(value.objectId) &&
672				isGenerationId(value.generationId) &&
673				isBlobDigest(value.digest)
674			);
675		}
676	
677		private blobMatches(reference: GenerationRef, blob: Uint8Array): boolean {
678			if (blob.byteLength !== reference.byteLength) return false;
679			const digest = digestBlob(blob);
680			return digest.ok && digest.value === reference.digest;
681		}
682	
683		private promotionKey(objectId: StorageObjectId, generationId: GenerationId, digest: BlobDigest): string {
684			return `${objectId}\0${generationId}\0${digest}`;
685		}
686	}
687	
688	function firstGenerationAfter(generationIds: readonly GenerationId[], afterGenerationId: GenerationId | null): number {
689		if (afterGenerationId === null) return 0;
690		let lower = 0;
691		let upper = generationIds.length;
692		while (lower < upper) {
693			const middle = lower + Math.floor((upper - lower) / 2);
694			const generationId = generationIds[middle];
695			if (generationId === undefined) throw new Error("ordered generation index is sparse");
696			if (compareCanonicalText(generationId, afterGenerationId) <= 0) lower = middle + 1;
697			else upper = middle;
698		}
699		return lower;
700	}
701	
702	function insertGenerationId(generationIds: GenerationId[], generationId: GenerationId): void {
703		const index = firstGenerationAfter(generationIds, generationId);
704		generationIds.splice(index, 0, generationId);
705	}
706	
707	function indexedGeneration(object: MutableObject, generationId: GenerationId): MutableGeneration {
708		const generation = object.generations.get(generationId);
709		if (generation === undefined) throw new Error("ordered generation index disagrees with the journal");
710		return generation;
711	}
712	
713	function indexedGenerationRecord(object: MutableObject, generationId: GenerationId): GenerationRecord {
714		return asRecord(indexedGeneration(object, generationId));
715	}

