142	function exactKeyPath(actual: string | string[] | null, expected: string | readonly string[] | null): boolean {
143		if (!Array.isArray(expected)) return actual === expected;
144		return (
145			Array.isArray(actual) &&
146			actual.length === expected.length &&
147			actual.every((part, index) => part === expected[index])
