151	function hasExactSchema(
152		database: IDBDatabase,
153		authority:
154			| typeof PHASE_2D_SCHEMA_AUTHORITY
155			| typeof PHASE_5C_LEGACY_SCHEMA_AUTHORITY
156			| typeof PHASE_5C_SCHEMA_AUTHORITY
157			| typeof PHASE_5E_SCHEMA_AUTHORITY,
158		transaction?: IDBTransaction,
159		ignoreVersion = false
160	): boolean {
161		if (
162			(!ignoreVersion && database.version !== authority.version) ||
163			database.objectStoreNames.length !== authority.stores.length ||
164			authority.stores.some((store) => !database.objectStoreNames.contains(store.name))
165		) {
166			return false;
167		}
168	
169		try {
170			const selectedTransaction = transaction ?? database.transaction(authority.stores.map((store) => store.name));
171			return authority.stores.every((expectedStore) => {
172				const actualStore = selectedTransaction.objectStore(expectedStore.name);
173				if (
174					actualStore.autoIncrement !== expectedStore.autoIncrement ||
175					!exactKeyPath(actualStore.keyPath, expectedStore.keyPath) ||
176					actualStore.indexNames.length !== 0
177				) {
178					return false;
179				}
180				return true;
181			});
182		} catch {
183			return false;
184		}
185	}
