228	function openDatabase(databaseName: string, onVersionChange?: () => void): Promise<IDBDatabase> {
229		return new Promise((resolve, reject) => {
230			const request = indexedDB.open(databaseName, PHASE_5E_SCHEMA_VERSION);
231			let blockedTimer: ReturnType<typeof setTimeout> | undefined;
232			let settled = false;
233			const clearBlockedTimer = (): void => {
234				if (blockedTimer !== undefined) clearTimeout(blockedTimer);
235			};
236			request.addEventListener(
237				"upgradeneeded",
238				(event) => {
239					const transaction = request.transaction;
240					if (
241						settled ||
242						transaction === null ||
243						(event.oldVersion !== 0 && event.oldVersion !== 1 && event.oldVersion !== 2)
244					) {
245						request.transaction?.abort();
246						return;
247					}
248					if (event.oldVersion === 0) {
249						if (request.result.objectStoreNames.length !== 0) {
250							transaction.abort();
251							return;
252						}
253						createStores(request.result, PHASE_5E_SCHEMA_AUTHORITY.stores);
254						transaction.objectStore(PHASE_5C_STORAGE_META_STORE).add({
255							key: "incarnation",
256							value: randomIncarnation(),
257						});
258					} else if (event.oldVersion === 1) {
259						if (!hasExactSchema(request.result, PHASE_2D_SCHEMA_AUTHORITY, transaction, true)) {
260							transaction.abort();
261							return;
262						}
263						createStores(request.result, PHASE_5E_SCHEMA_AUTHORITY.stores.slice(PHASE_2D_SCHEMA_AUTHORITY.stores.length));
264						transaction.objectStore(PHASE_5C_STORAGE_META_STORE).add({
265							key: "incarnation",
266							value: randomIncarnation(),
267						});
268					} else {
269						if (!hasExactSchema(request.result, PHASE_5C_LEGACY_SCHEMA_AUTHORITY, transaction, true)) {
270							transaction.abort();
271							return;
272						}
273						createStores(
274							request.result,
275							PHASE_5E_SCHEMA_AUTHORITY.stores.slice(PHASE_5C_LEGACY_SCHEMA_AUTHORITY.stores.length)
276						);
277					}
278				},
279				{ once: true }
280			);
281			request.addEventListener(
282				"blocked",
283				() => {
284					blockedTimer ??= setTimeout(() => {
285						if (settled) return;
286						settled = true;
287						reject(new BrowserStorageBlockedError());
288					}, PHASE_5C_BLOCKED_OPEN_TIMEOUT_MILLISECONDS);
289				},
290				{ once: true }
291			);
292			request.addEventListener(
293				"error",
294				() => {
295					if (settled) return;
296					settled = true;
297					clearBlockedTimer();
298					reject(classifyOpenError(request.error));
299				},
300				{ once: true }
301			);
302			request.addEventListener(
303				"success",
304				() => {
305					const database = request.result;
306					if (settled) {
307						database.close();
308						return;
309					}
310					if (!hasExactSchema(database, PHASE_5E_SCHEMA_AUTHORITY)) {
311						database.close();
312						settled = true;
313						clearBlockedTimer();
314						reject(new BrowserStorageSchemaError());
315						return;
316					}
317					database.addEventListener("versionchange", () => {
318						database.close();
319						onVersionChange?.();
320					});
321					settled = true;
322					clearBlockedTimer();
323					resolve(database);
324				},
325				{ once: true }
326			);
327		});
328	}
