226	function validProjection(material: CreatorAdoptionIntentMaterial): Readonly<Record<string, unknown>> | undefined {
227		const descriptor = canonicalRecord(material.exactCanonicalProjectionBytes);
228		if (descriptor?.kind !== "v3-live-generation-2") return undefined;
229		const digest = digestBlob(material.exactCanonicalProjectionBytes);
230		if (!digest.ok) return undefined;
231		const projectionRef = Object.freeze({
232			byteLength: material.exactCanonicalProjectionBytes.byteLength,
233			digest: digest.value,
234		});
235		const predecessorAclDigest = digestBlob(material.activation.predecessorExactCanonicalLatchedAclBytes);
236		if (!predecessorAclDigest.ok) return undefined;
237		const predecessorAclRef = Object.freeze({
238			byteLength: material.activation.predecessorExactCanonicalLatchedAclBytes.byteLength,
239			digest: predecessorAclDigest.value,
240		});
241		const retained = material.pendingReferences.filter((ref) => !sameRef(ref, material.predecessorLiveRef));
242		const derived = Object.freeze(
243			[
244				...retained,
245				projectionRef,
246				...(retained.some((ref) => sameRef(ref, predecessorAclRef)) ? [] : [predecessorAclRef]),
247			].sort((left, right) => (left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0))
248		);
249		return material.pendingReferences.filter((ref) => sameRef(ref, material.predecessorLiveRef)).length === 1 &&
250			new Set(derived.map(({ digest: value }) => value)).size === derived.length &&
251			sameClosure(derived, material.candidateReferences)
252			? Object.freeze(descriptor)
253			: undefined;
254	}
