235	async function readGenerationLineage(
236		store: AheDurableStore,
237		objectId: StorageObjectId
238	): Promise<readonly GenerationRecord[] | undefined> {
239		const generations: GenerationRecord[] = [];
240		const seenCursors = new Set<GenerationPageCursor>();
241		let cursor: GenerationPageCursor | undefined;
242		for (;;) {
243			const page = await store.readGenerationPage({
244				...(cursor === undefined ? {} : { cursor }),
245				limit: 128,
246				objectId,
247			});
248			if (!page.ok || (page.value.generations.length === 0 && page.value.nextCursor !== null)) return undefined;
249			generations.push(...page.value.generations);
250			if (page.value.nextCursor === null) return Object.freeze(generations);
251			if (seenCursors.has(page.value.nextCursor)) return undefined;
252			seenCursors.add(page.value.nextCursor);
253			cursor = page.value.nextCursor;
254		}
255	}
